from .base import AppServerRunner
from .ping_analyzer import PingAnalyzer


class PingDataTransfer(AppServerRunner):
    """Ping Data Transfer"""
    def __init__(self, command_tail, app_server_ip, app_server_username, app_server_password, app_server_lte_ip, logger,
                 **kwargs):
        """
        :param target_ip:
        :param app_server_ip:
        :param app_server_username:
        :param app_server_password:
        :param app_server_lte_ip:
        :param logger:
        :param logs_path:
        """
        super(PingDataTransfer, self).__init__(app_server_ip=app_server_ip,
                                               app_server_username=app_server_username,
                                               app_server_password=app_server_password,
                                               app_server_lte_ip=app_server_lte_ip,
                                               logger=logger)

        analyzer_params = kwargs.get('analyzer_params')
        self.analyzer = self._create_analyzer(logger, analyzer_params)
        self.command_tail = command_tail

    def run(self):
        """Starts ping"""
        command = "ping {}".format(self.command_tail)
        self._run_loop(command)

    def _create_analyzer(self, logger, analyzer_params):
        return PingAnalyzer(logger, **analyzer_params)
